firmware:
const int BTN = 4;
int last = HIGH;

void setup() {
  Serial.begin(115200);
  pinMode(BTN, INPUT_PULLUP);
}

void loop() {
  int now = digitalRead(BTN);
  if (last == HIGH && now == LOW) {
    delay(30);
    if (digitalRead(BTN) == LOW) {
      Serial.println("PRESSED");
    }
  }
  last = now;
  delay(5);
}
